const 妫€鏌ラ€変腑鍏冪礌鐘舵€?= (selectsElement: Element[]): { isList: boolean; isContinue: boolean } => {
    let isList = false;
    let isContinue = false;

    // @鍐呰仈鍥炶皟
    selectsElement.find((item, index) => {
        if (item.classList.contains("li")) {
            isList = true;
            return true;
        }
        const 涓嬩竴涓€変腑鍏冪礌 = selectsElement[index + 1];
        if (item.nextElementSibling && 涓嬩竴涓€変腑鍏冪礌 &&
            item.nextElementSibling === 涓嬩竴涓€変腑鍏冪礌) {
            isContinue = true;
        } else if (index !== selectsElement.length - 1) {
            isContinue = false;
            return true;
        }
    });

    return { isList, isContinue };
};

