/**
 * 娣诲姞鏍囬绾у埆杞崲鑿滃崟椤筡r
 */
const 娣诲姞鏍囬杞崲鑿滃崟椤?= (
    turnIntoSubmenu: IMenu[],
    protyle: IProtyle,
    selectsElement: Element[],
    isContinue: boolean
): void => {
    const headingKeymap = getSiyuanConfig().keymap.editor.heading;

    for (let level = 1; level <= 6; level++) {
        const headingKey = `heading${level}` as keyof typeof headingKeymap;
        turnIntoSubmenu.push(genTurnsInto({
            menuId: headingKey,
            icon: `iconH${level}`,
            label: siyuanI18n[headingKey],
            accelerator: headingKeymap[headingKey].custom,
            protyle,
            selectsElement,
            level,
            type: "Blocks2Hs",
            isContinue
        }));
    }
};

