/**
 * 鏋勫缓AI鑿滃崟
 */
const 鏋勫缓AI鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    if (protyle.disabled) {
        return;
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "ai",
        icon: "iconSparkles",
        label: siyuanI18n.ai,
        accelerator: getSiyuanConfig().keymap.editor.general.ai.custom,
        click() {
            openAIActionsMenu(selectsElement, protyle);
        }
    }).element);
};

/**
 * 鏋勫缓澶嶅埗鑿滃崟
 */
const 鏋勫缓澶嶅埗鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    const nodeIds = Array.from(selectsElement).map(item => item.getAttribute("data-node-id"));

    const copyMenu: IMenu[] = (copySubMenu(nodeIds, true, selectsElement[0]) as IMenu[]).concat([{
        id: "copyPlainText",
        iconHTML: "",
        label: siyuanI18n.copyPlainText,
        accelerator: getSiyuanConfig().keymap.editor.general.copyPlainText.custom,
        click() {
            let html = "";
            for (const item of selectsElement) {
                html += getPlainText(item as HTMLElement) + "\n";
            }
            copyPlainText(html.trimEnd());
            focusBlock(selectsElement[0]);
        }
    }, {
        id: "copy",
        iconHTML: "",
        label: siyuanI18n.copy,
        accelerator: "鈱楥",
        click() {
            if (isNotEditBlock(selectsElement[0])) {
                focusBlock(selectsElement[0]);
            } else {
                focusByRange(getEditorRange(selectsElement[0]));
            }
            document.execCommand("copy");
        }
    }]);

    const copyTextRefMenu = genCopyTextRef(Array.from(selectsElement));
    if (copyTextRefMenu) {
        copyMenu.splice(7, 0, copyTextRefMenu);
    }

    if (!protyle.disabled) {
        copyMenu.push({
            id: "duplicate",
            iconHTML: "",
            label: siyuanI18n.duplicate,
            accelerator: getSiyuanConfig().keymap.editor.general.duplicate.custom,
            click() {
                duplicateBlock(selectsElement, protyle);
            }
        });
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "copy",
        label: siyuanI18n.copy,
        icon: "iconCopy",
        type: "submenu",
        submenu: copyMenu,
    }).element);
};

/**
 * 鏋勫缓缂栬緫鎿嶄綔鑿滃崟锛堝壀鍒囥€佺Щ鍔ㄣ€佸垹闄ょ瓑锛塡r
 */
const 鏋勫缓缂栬緫鎿嶄綔鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    if (protyle.disabled) {
        return;
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "cut",
        label: siyuanI18n.cut,
        accelerator: "鈱榅",
        icon: "iconCut",
        click: () => {
            focusBlock(selectsElement[0]);
            document.execCommand("cut");
        }
    }).element);

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "move",
        label: siyuanI18n.move,
        accelerator: getSiyuanConfig().keymap.general.move.custom,
        icon: "iconMove",
        click: () => {
            movePathTo({
                // @鍐呰仈鍥炶皟
                cb: (toPath) => {
                    hintMoveBlock(toPath[0], selectsElement, protyle);
                },
                flashcard: false
            });
        }
    }).element);

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "addToDatabase",
        label: siyuanI18n.addToDatabase,
        accelerator: getSiyuanConfig().keymap.general.addToDatabase.custom,
        icon: "iconDatabase",
        click: () => {
            addEditorToDatabase(protyle, getEditorRange(selectsElement[0]));
        }
    }).element);

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "delete",
        label: siyuanI18n.delete,
        icon: "iconTrashcan",
        accelerator: "鈱玕

Backspace");
        }
    }).element);
};

/**
 * 鏋勫缓澶栬鑿滃崟
 */
const 鏋勫缓澶栬鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    if (protyle.disabled) {
        return;
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem({ id: "separator_appearance", type: "separator" }).element);

    const appearanceElement = new MenuItem({
        id: "appearance",
        label: siyuanI18n.appearance,
        icon: "iconFont",
        accelerator: getSiyuanConfig().keymap.editor.insert.appearance.custom,
        click: () => {
            /// #if MOBILE
            showMobileAppearance(protyle);
            /// #else
            protyle.toolbar.element.classList.add("fn__none");
            protyle.toolbar.subElement.innerHTML = "";
            protyle.toolbar.subElement.style.width = "";
            protyle.toolbar.subElement.style.padding = "";
            protyle.toolbar.subElement.append(appearanceMenu(protyle, selectsElement));
            protyle.toolbar.subElement.style.zIndex = (++window.siyuan.zIndex).toString();
            protyle.toolbar.subElement.classList.remove("fn__none");
            protyle.toolbar.subElementCloseCB = undefined;
            const position = selectsElement[0].getBoundingClientRect();
            setPosition(protyle.toolbar.subElement, position.left, position.top);
            /// #endif
        }
    }).element;

    getSiyuanGlobalMenus().menu.append(appearanceElement);

    if (!isMobile()) {
        appearanceElement.lastElementChild.classList.add("b3-menu__submenu--row");
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem(buildGutterAlignMenu(selectsElement, protyle)).element);
    getSiyuanGlobalMenus().menu.append(new MenuItem(buildGutterWidthsMenu(selectsElement, protyle)).element);
};

/**
 * 鏋勫缓闂崱鑿滃崟
 */
const 鏋勫缓闂崱鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    if (getSiyuanConfig().readonly) {
        return;
    }

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "separator_quickMakeCard",
        type: "separator"
    }).element);

    const allCardsMade = !selectsElement.some(item =>
        !item.hasAttribute(Constants.CUSTOM_RIFF_DECKS) &&
        item.getAttribute("data-type") !== "NodeThematicBreak"
    );

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: allCardsMade ? "removeCard" : "quickMakeCard",
        label: allCardsMade ? siyuanI18n.removeCard : siyuanI18n.quickMakeCard,
        accelerator: getSiyuanConfig().keymap.editor.general.quickMakeCard.custom,
        icon: "iconRiffCard",
        click() {
            quickMakeCard(protyle, selectsElement);
        }
    }).element);

    getSiyuanGlobalMenus().menu.append(new MenuItem({
        id: "addToDeck",
        label: siyuanI18n.addToDeck,
        icon: "iconRiffCard",
        ignore: !getSiyuanConfig().flashcard.deck,
        click() {
            const ids: string[] = [];
            for (const item of selectsElement) {
                if (item.getAttribute("data-type") === "NodeThematicBreak") {
                    continue;
                }
                ids.push(item.getAttribute("data-node-id"));
            }
            makeCard(protyle.app, ids);
        }
    }).element);
};

/**
 * 瑙﹀彂鎻掍欢鑿滃崟浜嬩欢
 */
const 瑙﹀彂鎻掍欢鑿滃崟 = (protyle: IProtyle, selectsElement: Element[]): void => {
    if (!protyle?.app?.plugins) {
        return;
    }

    emitOpenMenu({
        plugins: protyle.app.plugins,
        type: "click-blockicon",
        detail: {
            protyle,
            blockElements: selectsElement,
        },
        separatorPosition: "top",
    });
};

/**
 * 鏋勫缓澶氶€夊潡鐨勫彸閿彍鍗昞r
 * @param ctx 澶氶€夊潡鑿滃崟涓婁笅鏂嘰r
 * @returns 鑿滃崟瀵硅薄
 */
export const buildGutterMultipleMenu = (ctx: IGutterMultipleMenuContext) => {
    const { protyle, selectsElement } = ctx;
    const { isList, isContinue } = 妫€鏌ラ€変腑鍏冪礌鐘舵€?selectsElement);

    // 1. 杞崲涓鸿彍鍗昞r
    鏋勫缓杞崲鑿滃崟(protyle, selectsElement, isList, isContinue);

    // 2. AI 鑿滃崟
    鏋勫缓AI鑿滃崟(protyle, selectsElement);

    // 3. 澶嶅埗鑿滃崟
    鏋勫缓澶嶅埗鑿滃崟(protyle, selectsElement);

    // 4. 缂栬緫鎿嶄綔鑿滃崟
    鏋勫缓缂栬緫鎿嶄綔鑿滃崟(protyle, selectsElement);

    // 5. 澶栬鑿滃崟
    鏋勫缓澶栬鑿滃崟(protyle, selectsElement);

    // 6. 闂崱鑿滃崟
    鏋勫缓闂崱鑿滃崟(protyle, selectsElement);

    // 7. 鎻掍欢鑿滃崟
    瑙﹀彂鎻掍欢鑿滃崟(protyle, selectsElement);

    return getSiyuanGlobalMenus().menu;
};
